{
  "scenes": [
    {
      "scene_id": "S1",
      "name": "杂乱桌面",
      "location": "办公桌近景",
      "intent": "建立共情，展示整理前的状态"
    },
    {
      "scene_id": "S2",
      "name": "三分钟整理流程",
      "location": "同一张办公桌，俯拍",
      "intent": "分步演示四个动作，强调可执行"
    },
    {
      "scene_id": "S3",
      "name": "整理后的空角",
      "location": "桌面右下角特写",
      "intent": "给出视觉落点与结果对比"
    }
  ],
  "shots": [
    {
      "shot_id": "SH01",
      "scene": "S1",
      "description": "俯拍整张桌面，键盘前方散落纸张、杯子、耳机与便签，画面上方叠开场钩子字幕。"
    },
    {
      "shot_id": "SH02",
      "scene": "S2",
      "description": "手部特写：把键盘前方一臂范围内的物品统一推到手边待处理区，动作一次性完成，不剪碎。"
    },
    {
      "shot_id": "SH03",
      "scene": "S2",
      "description": "中景俯拍三堆分类：今天要用、这周会用、暂时不用，字幕同步标注三堆名称。"
    },
    {
      "shot_id": "SH04",
      "scene": "S3",
      "description": "桌面右下角特写，空出一块干净区域，放上水杯与便利贴，光线略亮一点。"
    },
    {
      "shot_id": "SH05",
      "scene": "S3",
      "description": "回到俯拍全景，桌面清爽，收尾字幕"三分钟，眼睛少做选择"。"
    }
  ]
}
